def transform(grid):
    """Add color-2 exterior and color-3 interior one-cell rims around 1-walled cavities."""
    h, w = len(grid), len(grid[0])
    outside = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and not outside[nr][nc]:
                outside[nr][nc] = True
                q.append((nr, nc))

    inside = [[grid[r][c] == 0 and not outside[r][c] for c in range(w)] for r in range(h)]
    # Only 1-components that border a cavity receive the two colored rims.
    seen = [[False] * w for _ in range(h)]
    rim_components = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or seen[r][c]:
                continue
            comp = []
            q = deque([(r, c)])
            seen[r][c] = True
            borders_inside = False
            while q:
                y, x = q.popleft()
                comp.append((y, x))
