                        if grid[ny][nx] == 1 and not seen[ny][nx]:
                            seen[ny][nx] = True
                            q.append((ny, nx))
            if borders_inside:
                components.append(comp)

    out = [row[:] for row in grid]
    # Inner one-cell rim, restricted to enclosed zero regions.
    for r in range(h):
        for c in range(w):
